function doubleArray(arr) {
  const result = [];

  for (const value of arr) {
    result.push(value * 2);
  }

  return result;
}

function findDuplicates(arr) {
  for (let i = 0; i < arr.length; i++) {
    for (let j = i + 1; j < arr.length; j++) {
      if (arr[i] === arr[j]) {
        return true;
      }
    }
  }

  return false;
}
